    uint32_t e=(uint32_t)(x>>52)&2047u;
    if (e<897u || e>1150u || (x & UINT64_C(0x1fffffff))) return 0;
    return sign | ((e-896u)<<23) | ((uint32_t)(x>>29)&UINT32_C(0x7fffff));
